from acdb2lcov import parse_acdb_xml, emit_lcov xml = open("coverage_report.xml").read()
report = parse_acdb_xml(xml)
open("coverage.info", "w").write(emit_lcov(report.files)) to_json / from_json handle serde-style round-trips through dataclasses.asdict + json.dumps — handy for persisting coverage across pipeline stages without re-parsing the XML.

